/* ============ offline topic banks ============ */
function offlineTopicKey(topic){
  const t=norm(topic);
  if(/არითმეტიკ.*პროგრეს.*(პირველი.*n|ჯამ)|arithmetic.*progress.*(first.*n|sum)/.test(t)) return 'apsum';
  if(/გეომეტრ.*პროგრეს.*(პირველი.*n|ჯამ)|geometric.*progress.*(first.*n|sum)/.test(t)) return 'gpsum';
  if(/გეომეტრ.*პროგრეს|geometric.*progress/.test(t)) return 'gp';
  if(/არითმეტიკ.*პროგრეს|arithmetic.*progress/.test(t)) return 'ap';
  if(/ეგვიპტ.*პირამიდ|პირამიდ.*ეგვიპტ|pyramids? of egypt|egyptian pyramid/.test(t)) return 'pyramids';
  if(/ნახევარ\s*-?\s*წარმოებ|half.?derivative|d\^?\(?1\/2/.test(t)) return 'half';
  if(/წარმოებულ|ზღვრის გარეშე|derivative without limits/.test(t)) return 'derivative';
  if(/ერთუცნობიან|ერთცვლადიან|მარტივ.*განტოლ|v კლას.*განტოლ|5 კლას.*განტოლ|grade 5 equation/.test(t)) return 'grade5_eq';
   if(/წრფივ.*განტოლ|linear.*equation/.test(t)) return 'linear_eq';
  if(/კვადრატ.*განტოლ|quadratic.*equation/.test(t)) return 'quadratic_eq';
  if(/პროპორც|proportion|ratio/.test(t)) return 'proportion';
  if(/წრფივ.*ფუნქც|linear.*function/.test(t)) return 'linear_fn';
  return null;
}
