     check:{type:'text',kw:t=>/(^|[^0-9.])5([^0-9]|$)/.test(t),errors:[{re:/(^|[^0-9.])6([^0-9]|$)/,err:'order_mult',follow:'D²∘D³: სამჯერ, შემდეგ ორჯერ. სულ რამდენჯერ ვაწარმოებთ? მაჩვენებლები მრავლდება თუ იკრიბება?'}]},
